import { coordinatesFor, installBaseLayers, roadRoute } from './modules/map-provider.js';
import { renderAdvanced } from './modules/advanced.js';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
let role=new URLSearchParams(location.search).get('role')||'owner';let customerId=new URLSearchParams(location.search).get('customer')||'';let data={};let activeView='';
const icons={fullworkspace:'▣',alerts:'! ',history:'↺',weather:'☀',routes:'⌖',documents:'▤',backup:'⇩',dashboard:'◫',leads:'◇',customers:'◎',quotes:'◆',schedule:'▦',jobs:'✓',billing:'▤',communications:'✉',team:'♧',operations:'⚒',reports:'⌁',settings:'⚙',today:'◉',navigation:'⌖',photos:'▧',portal:'⌂',services:'✦',messages:'✉'};
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=v=>new Intl.NumberFormat(data.tenant?.locale||'en-US',{style:'currency',currency:data.tenant?.currency||'USD',maximumFractionDigits:2}).format(Number(v||0));
const badge=s=>`<span class="badge b-${String(s||'').toLowerCase().replaceAll(' ','-')}">${esc(s||'—')}</span>`;const labels={fullworkspace:'Operations Workspace',routes:'Route Center',billing:'Invoices & Payments',communications:'Messages',operations:'Equipment & Inventory',documents:'Documents',photos:'Photos & Attachments'};const title=s=>labels[s]||s.charAt(0).toUpperCase()+s.slice(1);
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;$('#toastRoot').append(el);setTimeout(()=>el.remove(),2600)}
async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{'content-type':'application/json',...(opts.headers||{})}});const d=await r.json();if(!r.ok){const e=new Error(d.error||'Request failed');e.payload=d;throw e}return d}
async function load(view=activeView){try{data=await api(`/api/bootstrap?role=${role}${customerId?`&customer=${encodeURIComponent(customerId)}`:''}`);activeView=view&&data.permissions.includes(view)?view:data.permissions[0];renderChrome();render(activeView)}catch(e){$('#content').innerHTML=`<div class="empty-state"><h2>Unable to load workspace</h2><p>${esc(e.message)}</p></div>`}}
function renderChrome(){document.body.dataset.role=role;const t=data.tenant||{},b=t.brand||{};for(const [k,v] of Object.entries({'--accent':b.accent||'#5cff00','--accent-dark':b.accentDark||'#27c600','--highlight':b.highlight||'#ff7a00','--gold':b.gold||'#ffbd46','--nav':b.nav||'#050606'}))document.documentElement.style.setProperty(k,v);$('#brandLogo').src=b.appLogoUrl||b.logoUrl||'/app/assets/paradise-logo-master.png';$('#platformBrand').textContent=t.shortName||t.name;$('#tenantName').textContent=t.name;$('#tenantMeta').textContent=t.serviceArea||t.vertical;$('#roleSelect').value=role;$('#avatar').textContent=(data.user?.name||'B').charAt(0).toUpperCase();document.title=`${t.shortName||t.name} — ${t.productName||'Business in a Box'}`;const visiblePermissions=data.permissions.filter(p=>p!=='fullworkspace');if(activeView==='fullworkspace')activeView='dashboard';$('#nav').innerHTML=visiblePermissions.map(p=>`<button class="nav-item ${p===activeView?'active':''}" data-view="${p}"><span>${icons[p]||'•'}</span>${title(p)}</button>`).join('');$$('.nav-item').forEach(b=>b.onclick=()=>{activeView=b.dataset.view;renderChrome();render(activeView);closeMenu()})}
function setHeader(a,b){$('#viewEyebrow').textContent=a;$('#pageTitle').textContent=b}function hero(a,b,c,d=''){return `<div class="hero-row"><div><span class="eyebrow">${a}</span><h2>${b}</h2><p>${c}</p></div><div class="hero-actions">${d}</div></div>`}function panel(a,b,c,d=''){return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">${b}</span><h3>${a}</h3></div>${d}</div>${c}</section>`}
function modal(title,body){closeModal();$('#modalRoot').innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><div class="modal-card"><div class="modal-head"><div><span class="eyebrow">${esc(data.tenant?.productName||'BUSINESS IN A BOX')}</span><h2>${title}</h2></div><button class="modal-x" id="modalX">×</button></div><div class="modal-body">${body}</div></div></div>`;$('#modalX').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()}}function closeModal(){$('#modalRoot').innerHTML=''}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}function textarea(label,name,value=''){return `<label class="field form-span"><span>${label}</span><textarea name="${name}" rows="4">${esc(value)}</textarea></label>`}function select(label,name,options,value=''){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const v=typeof o==='string'?o:o.value,l=typeof o==='string'?o:o.label;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`}
async function submit(form,path,method='POST',extras={}){const x={...Object.fromEntries(new FormData(form)),...extras};for(const k of ['amount','monthlyValue','balance','duration','price','rate','qty','reorderAt'])if(k in x)x[k]=Number(x[k]||0);return api(path,{method,body:JSON.stringify(x)})}
function render(v){if(role==='crew')return renderCrew(v);if(role==='customer')return renderCustomer(v);const ctx={$,$$,data,esc,money,badge,hero,panel,setHeader,api,toast,load,modal,closeModal,field,textarea,select};if(renderAdvanced(v,ctx))return;const map={dashboard,leads:leadsView,customers:customersView,quotes:quotesView,schedule:scheduleView,jobs:jobsView,billing:billingView,communications:communicationsView,team:teamView,operations:operationsView,reports:reportsView,settings:settingsView};(map[v]||dashboard)()}
function wireGo(){$$('[data-go]').forEach(b=>b.onclick=()=>{activeView=b.dataset.go;renderChrome();render(activeView)})}
function activityHtml(){return `<div class="activity">${data.activity.slice(0,9).map(a=>`<div><span class="activity-dot"></span><p>${esc(a.text)}<small>${esc(a.time)}</small></p></div>`).join('')}</div>`}
function dashboard(){
  setHeader('COMMAND CENTER',`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(data.user.name.split(' ')[0])}`);
  const m=data.metrics,t=data.tenant,allJobs=data.jobs||[],jobs=allJobs.slice(0,6),customers=data.customers||[],maint=data.maintenance||[],inv=data.inventory||[];
  const completed=allJobs.filter(j=>j.status==='Completed').length;
  const openQuotes=(data.quotes||[]).filter(q=>!['Accepted','Converted','Declined','Expired'].includes(q.status)).length;
  const next=allJobs.find(j=>!['Completed','Cancelled'].includes(j.status))||allJobs[0];
  const todayDate=new Date(); const end=new Date(todayDate); end.setDate(end.getDate()+7);
  const inNext7=allJobs.filter(j=>{const d=new Date(`${j.date}T12:00:00`);return !Number.isNaN(d)&&d>=new Date(todayDate.toDateString())&&d<end}).length;
  const weeklyRevenue=(data.invoices||[]).filter(i=>{const d=new Date(`${i.created}T12:00:00`);return !Number.isNaN(d)&&d>=new Date(Date.now()-7*86400000)}).reduce((sum,i)=>sum+Number(i.amount||0),0);
  const schedule=jobs.map(j=>`<div class="dash-schedule-row"><time>${esc(j.time)}</time><div><strong>${esc(j.customer)}</strong><small>${esc(j.address)} · ${esc(j.service)}</small></div><span class="mini-status ${j.status==='Completed'?'complete':j.status==='In progress'?'progress':''}">${esc(j.status)}</span></div>`).join('');
  const notes=customers.slice(0,4).map(c=>`<div class="note-item"><strong>${esc(c.name)}</strong><span>${esc(c.notes||'No special service notes.')}</span></div>`).join('');
  const equipment=[...maint.map(x=>({name:x.equipment,state:x.status||'Ready'})),{name:'Trailer',state:'Ready'},{name:'Trimmer / edger',state:'Ready'}].slice(0,5).map(x=>`<div class="equipment-item"><strong>${esc(x.name)}</strong><span class="equipment-ok">✓ ${esc(x.state)}</span></div>`).join('');
  $('#content').innerHTML=`<div class="mock-dashboard">
    <section class="brand-dew-strip weather-only-strip"><div class="dashboard-weather-label"><span>TREASURE COAST OPERATIONS</span><strong>Today’s operating weather</strong></div><div class="weather-strip" id="dashboardWeather"><div class="weather-glyph">☀</div><div><b>Weather Center</b><span>Loading Port St. Lucie conditions…</span></div></div></section>
    <div class="mock-metrics">
      <div class="mock-metric green"><i>👥</i><span><small>ACTIVE CUSTOMERS</small><b>${m.activeCustomers}</b><em>Recurring / active</em></span></div>
      <div class="mock-metric orange"><i>◆</i><span><small>PENDING QUOTES</small><b>${openQuotes}</b><em>Awaiting action</em></span></div>
      <div class="mock-metric blue"><i>▦</i><span><small>TODAY'S JOBS</small><b>${m.jobsToday}</b><em>${completed} completed overall</em></span></div>
      <div class="mock-metric green"><i>$</i><span><small>7-DAY INVOICED</small><b>${money(weeklyRevenue)}</b><em>Recorded invoices</em></span></div>
      <div class="mock-metric purple"><i>⌖</i><span><small>NEXT 7 DAYS</small><b>${inNext7}</b><em>Scheduled jobs</em></span></div>
      <div class="mock-metric blue"><i>→</i><span><small>NEXT JOB</small><b>${esc(next?.time||'—')}</b><em>${esc(next?.customer||'No stop scheduled')}</em></span></div>
    </div>
    <div class="mock-main-grid">
      <section class="mock-panel schedule-panel"><header><h3>Today's Schedule</h3><button class="tiny" data-go="schedule">View All</button></header>${schedule||'<div class="empty-row">No jobs scheduled</div>'}</section>
      <section class="mock-panel route-summary-panel"><header><h3>Route Center</h3><button class="tiny action-green" data-go="routes">Open Interactive Route</button></header><div class="dashboard-route-wrap"><div id="dashboardRouteMap" class="dashboard-route-map" aria-label="Today’s scheduled route map"></div><div class="route-preview-list">${allJobs.filter(j=>!['Completed','Cancelled'].includes(j.status)).slice(0,3).map((j,i)=>`<span><b>${i+1}</b>${esc(j.time)} · ${esc(j.customer)}<small>${esc(j.address)}</small></span>`).join('')||'<em>No active stops</em>'}</div></div></section>
      <div class="mock-side-stack">
        <section class="mock-panel quick-panel"><header><h3>Quick Actions</h3></header><div class="quick-grid"><button class="qa orange" data-go="quotes">＋ New Quote</button><button class="qa green" id="quickCustomer">👤 Add Customer</button><button class="qa blue" data-go="schedule">▦ Schedule Job</button><button class="qa purple" data-go="billing">▤ Create Invoice</button><button class="qa slate" data-go="communications">✉ Send Message</button><button class="qa slate" data-go="reports">⌁ View Reports</button></div></section>
        <section class="mock-panel"><header><h3>Recent Activity</h3><button class="tiny" data-go="history">View All</button></header>${activityHtml()}</section>
      </div>
    </div>
    <div class="mock-lower-grid">
      <section class="mock-panel"><header><h3>Customer Notes</h3><button class="tiny" data-go="customers">Customers</button></header><div class="note-list">${notes||'<div class="empty-row">No customer notes</div>'}</div></section>
      <section class="mock-panel"><header><h3>Equipment Status</h3><button class="tiny" data-go="operations">Manage</button></header><div class="equipment-list">${equipment}</div></section>
      <section class="mock-panel"><header><h3>Inventory Alerts</h3><button class="tiny" data-go="operations">Inventory</button></header>${inv.map(i=>`<div class="inventory-warning"><span><strong>${esc(i.name)}</strong>${esc(i.qty)} ${esc(i.unit)}</span><span class="${Number(i.qty)<=Number(i.reorderAt)?'warn':'positive'}">${Number(i.qty)<=Number(i.reorderAt)?'Reorder':'OK'}</span></div>`).join('')||'<div class="empty-row">No inventory items</div>'}</section>
      <section class="mock-panel tip-panel"><header><h3>Lawn Care Tip</h3></header><div class="tip-content"><div class="tip-art">🌱</div><div><strong>Rainy-season mowing</strong><p>Protect wet turf from rutting and scalping. Use the Learning Center for homeowner-facing guidance.</p><a href="/website/blog.html" target="_blank">Read lawn care articles →</a></div></div></section>
    </div>
    <footer class="dashboard-slogan">We Make Your Lawn <strong>PARADISE PERFECT</strong><span>☎ ${esc(t.phone||'')} · ${esc(t.email||'')}</span></footer>
  </div>`;
  wireGo(); $('#quickCustomer').onclick=()=>openCustomerForm(); loadDashboardWeather(); loadDashboardRouteMap(allJobs);
}

function dashboardJobCoordinate(job,index){ return coordinatesFor(job,index); }
async function loadDashboardRouteMap(allJobs=[]){
  const el=document.getElementById('dashboardRouteMap'),L=window.L;if(!el)return;
  if(!L){el.innerHTML='<div class="map-fallback"><strong>Map library unavailable</strong><span>Open Route Center for the scheduled stop list.</span></div>';return}
  const open=allJobs.filter(j=>!['Completed','Cancelled'].includes(j.status)).slice(0,9),pts=open.map(dashboardJobCoordinate);
  if(!pts.length){el.innerHTML='<div class="map-fallback"><strong>No active stops</strong><span>Scheduled jobs will appear here.</span></div>';return}
  const map=L.map(el,{zoomControl:false,scrollWheelZoom:false,dragging:false,doubleClickZoom:false,boxZoom:false,keyboard:false,tap:false,attributionControl:false});
  installBaseLayers(map,L,'satellite');
  pts.forEach((pt,i)=>L.marker(pt).addTo(map).bindTooltip(`${i+1}. ${open[i].customer}`,{direction:'top'}));
  let fit=pts;
  try{const route=await roadRoute(pts);if(route.geometry.length>1){L.polyline(route.geometry,{color:'#8dff3d',weight:5,opacity:.92}).addTo(map);fit=route.geometry}}
  catch{if(pts.length>1)L.polyline(pts,{color:'#ff8a1d',weight:3,opacity:.72,dashArray:'7 7'}).addTo(map)}
  map.fitBounds(L.latLngBounds(fit).pad(.12));setTimeout(()=>map.invalidateSize(),120);
}

async function loadDashboardWeather(){const box=$('#dashboardWeather');if(!box)return;const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),6000);try{const r=await fetch('https://api.open-meteo.com/v1/forecast?latitude=27.273&longitude=-80.3582&current=temperature_2m,weather_code&temperature_unit=fahrenheit&timezone=America%2FNew_York',{signal:controller.signal});clearTimeout(timer);if(!r.ok)throw new Error();const w=(await r.json()).current||{};box.innerHTML=`<div class="weather-glyph">🌤</div><div><b>${Math.round(w.temperature_2m||0)}°F · Port St. Lucie</b><span>Current reference conditions · Open Weather for details</span></div>`;box.onclick=()=>document.querySelector('.nav-item[data-view="weather"]')?.click();box.role='button';box.tabIndex=0}catch{clearTimeout(timer);box.innerHTML='<div class="weather-glyph">☁</div><div><b>Weather Center</b><span>Internet weather unavailable · open module for retry</span></div>';box.onclick=()=>document.querySelector('.nav-item[data-view="weather"]')?.click()}}
function leadTable(r){return `<div class="table">${r.map(x=>`<div class="tr"><div><strong>${esc(x.name)}</strong><span>${esc(x.service)} · ${esc(x.source)}</span></div><div><strong>${esc(x.address||'—')}</strong><small>${esc(x.created)}</small></div><div>${badge(x.status)}</div></div>`).join('')||'<div class="empty-row">No leads</div>'}</div>`}function jobTable(r){return `<div class="table">${r.map(x=>`<div class="tr"><div><strong>${esc(x.time)} · ${esc(x.customer)}</strong><span>${esc(x.service)} · ${esc(x.address)}</span></div><div><strong>${esc(x.crew)}</strong><small>${x.duration} min</small></div><div>${badge(x.status)}</div></div>`).join('')||'<div class="empty-row">No jobs</div>'}</div>`}function invoiceTable(r){return `<div class="table">${r.map(x=>`<div class="tr"><div><strong>${esc(x.id)}</strong><span>${esc(x.accountNumber||'')} · ${esc(x.customer)}</span></div><div><strong>${money(x.amount)}</strong><small>Paid ${money(x.paid||0)}</small></div><div>${badge(x.status)}</div></div>`).join('')||'<div class="empty-row">No invoices</div>'}</div>`}function requestTable(r){return `<div class="table">${r.map(x=>{const c=data.customers.find(c=>c.id===x.customerId);return `<div class="tr"><div><strong>${esc(x.type)}</strong><span>${esc(c?.name||'Customer')}</span></div><div><span>${esc(x.message)}</span><small>${esc(x.created)}</small></div><div>${badge(x.status)}</div></div>`}).join('')||'<div class="empty-row">No requests</div>'}</div>`}
function leadsView(){setHeader('SALES','Lead pipeline');$('#content').innerHTML=hero('LEADS','Lead pipeline','Website and office leads share the same record set.',`<button class="btn primary" id="addLead">+ New lead</button>`)+panel('Open opportunities',`${data.leads.length} LEADS`,`<div class="data-table"><div class="data-head"><span>Customer</span><span>Service</span><span>Source</span><span>Status</span><span>Actions</span></div>${data.leads.map(l=>`<div class="data-row"><span><strong>${esc(l.name)}</strong><small>${esc(l.address)}</small></span><span>${esc(l.service)}</span><span>${esc(l.source)}</span><span>${badge(l.status)}</span><span class="row-actions"><button class="tiny lead-edit" data-id="${l.id}">Edit</button><button class="tiny lead-customer" data-id="${l.id}">Make customer</button></span></div>`).join('')}</div>`);$('#addLead').onclick=()=>openLeadForm();$$('.lead-edit').forEach(b=>b.onclick=()=>openLeadForm(data.leads.find(x=>x.id===b.dataset.id)));$$('.lead-customer').forEach(b=>b.onclick=()=>convertLead(b.dataset.id))}
function openLeadForm(l={}){modal(l.id?'Edit lead':'New lead',`<form id="leadForm" class="form-grid">${field('Name','name',l.name,'text','required')}${field('Address','address',l.address)}${field('Phone','phone',l.phone)}${field('Email','email',l.email,'email')}${field('Service','service',l.service||data.services[0]?.name||'Service')}${select('Source','source',['Website','Google','Referral','Facebook','Office'],l.source||'Office')}${select('Status','status',['New','Contacted','Quoted','Follow-up','Won','Lost'],l.status||'New')}<div class="form-span"><button class="btn primary">${l.id?'Save changes':'Create lead'}</button></div></form>`);$('#leadForm').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,l.id?`/api/leads/${l.id}`:'/api/leads',l.id?'PUT':'POST');closeModal();toast('Lead saved');load('leads')}}
async function convertLead(id){const l=data.leads.find(x=>x.id===id);if(!l)return;try{await api('/api/customers',{method:'POST',body:JSON.stringify({name:l.name,email:l.email||'',phone:l.phone||'',property:l.address||'',plan:l.service,monthlyValue:data.services.find(s=>s.name===l.service)?.price||0,status:'Active'})});await api(`/api/leads/${id}`,{method:'PUT',body:JSON.stringify({status:'Won'})});toast('Lead converted to customer');load('customers')}catch(e){if(e.payload?.code==='DUPLICATE_CUSTOMER')return showDuplicates(e.payload.matches,()=>api('/api/customers',{method:'POST',body:JSON.stringify({name:l.name,email:l.email||'',phone:l.phone||'',property:l.address||'',plan:l.service,monthlyValue:0,status:'Active',allowDuplicate:true})}));throw e}}
function preferredAction(c){const m=c.preferredContact||'Phone';if(m==='Email'&&c.email)return `<a class="tiny action-green" href="mailto:${esc(c.email)}">Email</a>`;if(m==='Text'&&c.phone)return `<a class="tiny action-orange" href="sms:${esc(c.phone.replace(/[^0-9+]/g,''))}">Text</a>`;if(c.phone)return `<a class="tiny action-green" href="tel:${esc(c.phone.replace(/[^0-9+]/g,''))}">Call</a>`;return ''}
function customersView(){setHeader('CUSTOMERS','Customer accounts');$('#content').innerHTML=hero('CRM','Customers & properties','Permanent account numbers, multiple properties, preferred contact and billing policy carry into quotes, jobs and invoices.',`<button class="btn primary" id="addCustomer">+ New customer</button>`)+`<div class="customer-grid">${data.customers.map(c=>`<article class="customer-card"><div class="customer-card-head"><div class="avatar small">${esc(c.name[0])}</div><div><strong>${esc(c.name)}</strong><span>${esc(c.accountNumber)} · ${esc(c.status)}</span></div></div><p>${esc(c.property)}</p><div class="customer-facts"><span>Plan<strong>${esc(c.plan)}</strong></span><span>Billing<strong>${esc(c.billingMethod||'Per Service')}</strong></span><span>Contact<strong>${esc(c.preferredContact||'Phone')}</strong></span></div><div class="row-actions"><button class="tiny customer-edit action-green" data-id="${c.id}">Edit</button><button class="tiny property-add action-orange" data-id="${c.id}">+ Property</button><button class="tiny customer-portal" data-id="${c.id}">Portal</button>${preferredAction(c)}</div></article>`).join('')}</div>`;$('#addCustomer').onclick=()=>openCustomerForm();$$('.customer-edit').forEach(b=>b.onclick=()=>openCustomerForm(data.customers.find(x=>x.id===b.dataset.id)));$$('.property-add').forEach(b=>b.onclick=()=>openPropertyForm(data.customers.find(x=>x.id===b.dataset.id)));$$('.customer-portal').forEach(b=>b.onclick=()=>window.open(`/app?role=customer&customer=${encodeURIComponent(b.dataset.id)}`,'_blank'))}
function showDuplicates(matches,onContinue){modal('Possible duplicate customer',`<div class="settings-copy"><p>The account engine found a possible existing customer. This mirrors the safeguard from the Paradise 3.21B reference.</p>${matches.map(m=>`<div class="summary-box"><strong>${esc(m.accountNumber)} · ${esc(m.name)}</strong><span>${esc(m.phone)} · ${esc(m.email)}</span><span>${esc(m.property)}</span></div>`).join('')}<div class="form-span" style="margin-top:14px"><button class="btn secondary" id="cancelDup">Cancel</button> <button class="btn primary" id="forceDup">Create separate account anyway</button></div></div>`);$('#cancelDup').onclick=closeModal;$('#forceDup').onclick=async()=>{await onContinue();closeModal();toast('Separate account created');load('customers')}}
function openCustomerForm(c={}){modal(c.id?`Edit ${esc(c.accountNumber)}`:'New customer',`<form id="customerForm" class="form-grid">${field('Name','name',c.name,'text','required')}${field('Phone','phone',c.phone)}${field('Email','email',c.email,'email')}${field('Primary property','property',c.property,'text','required')}${field('Plan','plan',c.plan||data.services[0]?.name||'Service')}${field('Monthly value','monthlyValue',c.monthlyValue||0,'number','min="0" step="0.01"')}${select('Customer type','customerType',['Residential','Commercial','Property Management','HOA'],c.customerType||'Residential')}${select('Service frequency','serviceFrequency',['Weekly','Biweekly','Monthly','One Time','Seasonal'],c.serviceFrequency||'Weekly')}${select('Billing method','billingMethod',['Per Service','Bi-Weekly','Monthly','Manual'],c.billingMethod||'Per Service')}${field('Billing start / anchor','billingAnchor',c.billingAnchor||new Date().toISOString().slice(0,10),'date')}${select('Status','status',['Active','Paused','Prospect','Inactive'],c.status||'Active')}${select('Preferred contact','preferredContact',['Phone','Email','Text'],c.preferredContact||'Phone')}${select('Preferred payment','preferredPayment',['Invoice','Card','ACH','Cash','Check'],c.preferredPayment||'Invoice')}${textarea('Property / account notes','notes',c.notes||'')}<div class="form-span summary-box"><strong>Billing policy</strong><span>Per Service creates a ready-to-send invoice after completion. Bi-Weekly and Monthly group completed jobs into one invoice when the billing period matures. Manual leaves invoice creation to the office. Sending remains manual.</span></div><div class="form-span"><button class="btn primary">${c.id?'Save customer':'Create customer'}</button></div></form>`);$('#customerForm').onsubmit=async e=>{e.preventDefault();try{await submit(e.currentTarget,c.id?`/api/customers/${c.id}`:'/api/customers',c.id?'PUT':'POST');closeModal();toast('Customer saved');load('customers')}catch(err){if(err.payload?.code==='DUPLICATE_CUSTOMER'){const obj=Object.fromEntries(new FormData(e.currentTarget));showDuplicates(err.payload.matches,()=>api(c.id?`/api/customers/${c.id}`:'/api/customers',{method:c.id?'PUT':'POST',body:JSON.stringify({...obj,allowDuplicate:true})}))}else toast(err.message)}}}
function openPropertyForm(c){modal(`Add property · ${esc(c.accountNumber)}`,`<form id="propertyForm" class="form-grid">${field('Property label','label',`Property ${(c.properties?.length||0)+1}`)}${field('Address','address','','text','required')}${textarea('Service notes','serviceNotes','')}<div class="form-span"><button class="btn primary">Add property</button></div></form>`);$('#propertyForm').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,`/api/customers/${c.id}/properties`);closeModal();toast('Property added');load('customers')}}
function quoteActions(q){
  const a=[`<button class="tiny quote-edit" data-id="${q.id}">Edit</button>`];
  if(q.status==='Draft'){a.push(`<button class="tiny quote-state" data-id="${q.id}" data-status="Sent">Send</button>`);a.push(`<button class="tiny quote-state" data-id="${q.id}" data-status="Accepted">Accept</button>`)}
  else if(q.status==='Sent'){a.push(`<button class="tiny quote-state" data-id="${q.id}" data-status="Viewed">Mark viewed</button>`);a.push(`<button class="tiny quote-state" data-id="${q.id}" data-status="Accepted">Accept</button>`);a.push(`<button class="tiny quote-state" data-id="${q.id}" data-status="Declined">Decline</button>`)}
  else if(q.status==='Viewed'){a.push(`<button class="tiny quote-state" data-id="${q.id}" data-status="Accepted">Accept</button>`);a.push(`<button class="tiny quote-state" data-id="${q.id}" data-status="Declined">Decline</button>`)}
  else if(q.status==='Accepted'){a.push(`<button class="tiny quote-convert" data-id="${q.id}">${q.customerId?'Create job':'Create customer + job'}</button>`)}
  else if(q.status==='Converted'&&q.convertedJobId){a.push(`<button class="tiny quote-job" data-id="${q.convertedJobId}">Open jobs</button>`)}
  return a.join('');
}
function quotesView(){setHeader('SALES','Quotes');$('#content').innerHTML=hero('QUOTES','Quotes','A quote moves through explicit states. Acceptance and conversion are separate so an accepted quote can never become a dead end.',`<button class="btn primary" id="addQuote">+ New quote</button>`)+panel('Quote register',`${data.quotes.length} QUOTES`,`<div class="data-table"><div class="data-head"><span>Quote</span><span>Customer / prospect</span><span>Amount</span><span>Status</span><span>Actions</span></div>${data.quotes.map(q=>`<div class="data-row"><span><strong>${esc(q.id)}</strong><small>${esc(q.accountNumber||'Prospect')}</small></span><span>${esc(q.customer||'Unnamed prospect')}<small>${esc(q.service)}</small></span><span>${money(q.amount)}</span><span>${badge(q.status)}</span><span class="row-actions">${quoteActions(q)}</span></div>`).join('')}</div>`);$('#addQuote').onclick=()=>openQuoteForm();$$('.quote-edit').forEach(b=>b.onclick=()=>openQuoteForm(data.quotes.find(x=>x.id===b.dataset.id)));$$('.quote-state').forEach(b=>b.onclick=async()=>{try{await api(`/api/quotes/${encodeURIComponent(b.dataset.id)}/status`,{method:'POST',body:JSON.stringify({status:b.dataset.status})});toast(`Quote marked ${b.dataset.status.toLowerCase()}`);load('quotes')}catch(e){toast(e.message)}});$$('.quote-convert').forEach(b=>b.onclick=async()=>{try{const r=await api(`/api/quotes/${encodeURIComponent(b.dataset.id)}/convert`,{method:'POST',body:'{}'});toast(r.alreadyConverted?'Quote was already converted':`Created ${r.customer?.accountNumber||'customer'} · ${r.job?.id||'job'}`);load('quotes')}catch(e){toast(e.message)}});$$('.quote-job').forEach(b=>b.onclick=()=>{activeView='jobs';renderChrome();render('jobs')})}
function openQuoteForm(q={}){const customerOptions=[{value:'__prospect__',label:'New prospect (no customer account yet)'},...data.customers.map(c=>({value:c.id,label:`${c.accountNumber} · ${c.name}`}))];const selected=q.customerId||'__prospect__';modal(q.id?`Edit ${q.id}`:'New quote',`<form id="quoteForm" class="form-grid">${select('Customer / prospect','customerId',customerOptions,selected)}<div id="prospectFields" class="form-span form-grid">${field('Prospect name','prospectName',q.customerId?'':q.customer,'text','required')}${field('Phone','prospectPhone',q.prospectPhone||'')}${field('Email','prospectEmail',q.prospectEmail||'','email')}${field('Service address','prospectAddress',q.prospectAddress||'')}</div>${select('Service','service',data.services.map(s=>s.name),q.service||data.services[0]?.name)}${select('Preferred contact','preferredContact',['Phone','Email','Text'],q.preferredContact||data.customers.find(c=>c.id===q.customerId)?.preferredContact||'Phone')}${field('Amount','amount',q.amount||data.services[0]?.price||0,'number','min="0" step="0.01"')}<label class="field"><span>Workflow status</span><input value="${esc(q.status||'Draft')}" disabled></label>${textarea('Scope / notes','notes',q.notes||'')}<div class="form-span"><button class="btn primary">Save quote</button></div></form>`);const form=$('#quoteForm'),sel=form.elements.customerId,pf=$('#prospectFields');const toggle=()=>{const prospect=sel.value==='__prospect__';pf.style.display=prospect?'grid':'none';const n=form.elements.prospectName;if(n)n.required=prospect};sel.onchange=toggle;toggle();form.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),isProspect=f.get('customerId')==='__prospect__',c=isProspect?null:data.customers.find(x=>x.id===f.get('customerId'));const payload={customerId:c?.id||'',customer:c?.name||f.get('prospectName')||'',propertyId:c?.primaryPropertyId||'',prospectName:isProspect?f.get('prospectName'):'',prospectPhone:isProspect?f.get('prospectPhone'):'',prospectEmail:isProspect?f.get('prospectEmail'):'',prospectAddress:isProspect?f.get('prospectAddress'):'',service:f.get('service'),preferredContact:f.get('preferredContact'),amount:Number(f.get('amount')||0),notes:f.get('notes')};await api(q.id?`/api/quotes/${encodeURIComponent(q.id)}`:'/api/quotes',{method:q.id?'PUT':'POST',body:JSON.stringify(payload)});closeModal();toast(q.id?'Quote updated':'Draft quote created');load('quotes')}}
function scheduleView(){setHeader('OPERATIONS','Schedule');const sorted=[...data.jobs].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const base=new Date(),days=Array.from({length:7},(_,i)=>{const d=new Date(base);d.setDate(base.getDate()+i);return d.toISOString().slice(0,10)});$('#content').innerHTML=hero('SCHEDULE','Seven-day schedule & route handoff','The calendar, crew assignment, customer contact and Route Center all use the same live job records.',`<button class="btn primary" id="addJob">+ Schedule job</button>`)+`<div class="week-board">${days.map(d=>{const js=sorted.filter(j=>j.date===d);return `<section class="week-day"><header><b>${new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'})}</b><span>${new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></header>${js.map(j=>`<article><strong>${esc(j.time)} · ${esc(j.customer)}</strong><span>${esc(j.service)}</span><small>${esc(j.crew)} · ${j.duration} min</small></article>`).join('')||'<p>No jobs</p>'}</section>`}).join('')}</div>`+panel('Scheduled work',`${sorted.length} JOBS`,`<div class="data-table"><div class="data-head"><span>Date / time</span><span>Customer</span><span>Crew</span><span>Status</span><span>Actions</span></div>${sorted.map(j=>{const c=data.customers.find(x=>x.id===j.customerId);return `<div class="data-row"><span><strong>${esc(j.date)}</strong><small>${esc(j.time)}</small></span><span>${esc(j.customer)}<small>${esc(j.address)}</small></span><span>${esc(j.crew)}</span><span>${badge(j.status)}</span><span class="row-actions"><button class="tiny job-edit" data-id="${j.id}">Edit</button>${c?.phone?`<a class="tiny action-orange" href="sms:${esc(c.phone.replace(/[^0-9+]/g,''))}">Text</a>`:''}${c?.email?`<a class="tiny action-green" href="mailto:${esc(c.email)}">Email</a>`:''}<button class="tiny" data-go="routes">Route</button></span></div>`}).join('')}</div>`);$('#addJob').onclick=()=>openJobForm();$$('.job-edit').forEach(b=>b.onclick=()=>openJobForm(data.jobs.find(x=>x.id===b.dataset.id)));wireGo()}
