function billingView(){setHeader('FINANCE','Billing center');const q=data.billingQueue||[],ready=q.filter(g=>g.period?.ready),pending=q.filter(g=>!g.period?.ready),readySend=data.invoices.filter(i=>i.status==='Ready to Send'||i.communicationStatus==='Ready to Send');$('#content').innerHTML=hero('BILLING','Invoices & billing cycles','Completed services follow each customer’s Per Service, Bi-Weekly, Monthly or Manual billing policy. Invoices are populated automatically but sending remains under owner control.',`<button class="btn primary" id="processBilling">Process ready billing</button>`)+`<div class="metrics"><div class="metric"><span>READY BATCHES</span><strong>${ready.length}</strong><small>Eligible to populate now</small></div><div class="metric"><span>PENDING PERIODS</span><strong>${pending.length}</strong><small>Completed work still accumulating</small></div><div class="metric"><span>READY TO SEND</span><strong>${readySend.length}</strong><small>Owner review required</small></div><div class="metric"><span>UNBILLED WORK</span><strong>${money(data.billingSummary?.unbilledTotal||0)}</strong><small>Completed services not yet invoiced</small></div></div>`+`<div class="grid two">${panel('Billing queue','COMPLETED SERVICES',`<div class="table">${q.map(g=>`<div class="tr"><div><strong>${esc(g.customer.name)} · ${esc(g.method)}</strong><span>${esc(g.period.label)}</span></div><div><strong>${money(g.total)}</strong><small>${g.jobs.length} completed service${g.jobs.length===1?'':'s'}</small></div><div>${badge(g.period.ready?'Ready':'Accumulating')}</div></div>`).join('')||'<div class="empty-row">No unbilled completed services</div>'}</div>`)}`+`${panel('Ready to send','MANUAL SEND CONTROL',`<div class="table">${readySend.map(i=>`<div class="tr"><div><strong>${esc(i.id)}</strong><span>${esc(i.customer)} · ${esc(i.billingMethod||'Manual')}</span></div><div><strong>${money(i.amount)}</strong><small>${esc(i.billingPeriod||'')}</small></div><div><button class="tiny invoice-send action-green" data-id="${i.id}">Mark sent</button></div></div>`).join('')||'<div class="empty-row">Nothing waiting to send</div>'}</div>`)}</div>`+panel('Invoice register',`${data.invoices.length} INVOICES`,`<div class="data-table"><div class="data-head"><span>Invoice</span><span>Customer</span><span>Amount</span><span>Status</span><span>Actions</span></div>${data.invoices.map(i=>`<div class="data-row"><span><strong>${esc(i.id)}</strong><small>${esc(i.accountNumber||'')}</small></span><span>${esc(i.customer)}<small>${esc(i.billingMethod||'')} ${esc(i.billingPeriod||'')}</small></span><span>${money(i.amount)}<small>Paid ${money(i.paid||0)}</small></span><span>${badge(i.status)}</span><span>${i.status!=='Paid'?`<button class="tiny pay-invoice" data-id="${i.id}">Record payment</button>`:'—'}</span></div>`).join('')}</div>`);$('#processBilling').onclick=async()=>{const r=await api('/api/billing/process',{method:'POST',body:'{}'});toast(`${r.created?.length||0} invoice(s) populated`);load('billing')};$$('.invoice-send').forEach(b=>b.onclick=async()=>{const i=data.invoices.find(x=>x.id===b.dataset.id),c=data.customers.find(x=>x.id===i.customerId),channel=c?.preferredContact||'Email';await api(`/api/invoices/${encodeURIComponent(i.id)}/send`,{method:'POST',body:JSON.stringify({channel})});toast(`${i.id} marked sent by ${channel}`);load('billing')});$$('.pay-invoice').forEach(b=>b.onclick=()=>openPayment(b.dataset.id))}
