function renderCrew(v){if(v==='today'||v==='jobs'){setHeader('CREW','Today’s route');$('#content').innerHTML=hero('FIELD MODE','Crew route','The crew sees customer/property instructions and job status, not owner financial controls.')+`<div class="crew-list">${data.jobs.map((j,i)=>`<article class="crew-stop ${j.status==='In progress'?'current':''}"><div class="stop-no">${i+1}</div><div class="stop-main"><div class="stop-top"><strong>${esc(j.customer)}</strong>${badge(j.status)}</div><span>${esc(j.address)}</span><p>${esc(j.service)} · Est. ${j.duration} min${j.notes?` · ${esc(j.notes)}`:''}</p></div><div class="stop-actions">${j.status!=='Completed'?`<button class="btn ${j.status==='In progress'?'primary':'secondary'} crew-action" data-id="${j.id}" data-status="${j.status==='In progress'?'Completed':'In progress'}">${j.status==='In progress'?'Complete job':'Start job'}</button>`:''}</div></article>`).join('')}</div>`;$$('.crew-action').forEach(b=>b.onclick=async()=>{const r=await api(`/api/jobs/${encodeURIComponent(b.dataset.id)}/status`,{method:'POST',body:JSON.stringify({status:b.dataset.status})});toast(r.invoice?'Completed · invoice created':`Job ${b.dataset.status.toLowerCase()}`);load(v)});return}if(v==='navigation'){setHeader('CREW','Navigation');$('#content').innerHTML=hero('FIELD MODE','Route navigation','Prototype route order shares the schedule data.')+panel('Route order','TODAY',jobTable(data.jobs));return}setHeader('CREW','Photos');const atts=data.attachments||[];$('#content').innerHTML=hero('FIELD MODE','Job photos','Attach before, after, property or damage photos to the same job/customer record the office uses.')+`<div class="grid two"><section class="panel"><div class="panel-head"><div><span class="eyebrow">FIELD CAPTURE</span><h3>Add job photo</h3></div></div><form id="crewPhotoForm" class="form-grid">${select('Job','jobId',data.jobs.map(j=>({value:j.id,label:`${j.time} · ${j.customer} · ${j.address}`})),data.jobs[0]?.id||'')}${select('Category','category',['Before','After','Property','Damage'],'Before')}${field('Caption','caption','')}${field('Image','photo','','file','accept="image/*" required')}<div class="form-span"><button class="btn primary">Save photo</button></div></form></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">RECENT CAPTURES</span><h3>${atts.length} photo${atts.length===1?'':'s'}</h3></div></div><div class="photo-grid">${atts.slice(0,9).map(a=>`<figure class="photo-card"><img src="${esc(a.dataUrl)}" alt="${esc(a.caption||a.name)}"><figcaption><strong>${esc(a.category)}</strong><span>${esc(a.caption||a.name)}</span></figcaption></figure>`).join('')||'<div class="empty-state compact"><p>No job photos yet.</p></div>'}</div></section></div>`;$('#crewPhotoForm').onsubmit=e=>{e.preventDefault();const f=e.currentTarget,file=f.photo.files[0],j=data.jobs.find(x=>x.id===f.jobId.value);if(!file)return toast('Choose an image');if(file.size>5_000_000)return toast('Image is too large');const reader=new FileReader();reader.onload=async()=>{await api('/api/attachments',{method:'POST',body:JSON.stringify({jobId:j?.id||'',customerId:j?.customerId||'',propertyId:j?.propertyId||'',category:f.category.value,caption:f.caption.value,name:file.name,dataUrl:reader.result})});toast('Photo saved');load('photos')};reader.readAsDataURL(file)}}
function renderCustomer(v){const c=data.customer||data.customers[0];if(v==='portal'){setHeader('CUSTOMER PORTAL',`Welcome, ${esc(c.name.split(' ')[0])}`);$('#content').innerHTML=`<div class="portal-hero"><div><span class="eyebrow">${esc(data.tenant.shortName)}</span><h2>Your property, service and billing in one place.</h2><p>${esc(c.accountNumber)} · ${esc(c.property)}</p></div><button class="btn primary" data-go="services">View service</button></div><div class="metrics portal-metrics"><div class="metric"><span>NEXT SERVICE</span><strong>${esc(c.nextService||'To schedule')}</strong><small>${esc(c.plan)}</small></div><div class="metric"><span>ACCOUNT BALANCE</span><strong>${money(c.balance)}</strong><small>${c.balance?'Payment may be due':'Account current'}</small></div><div class="metric"><span>LAST SERVICE</span><strong>${esc(c.lastService||'—')}</strong><small>Service history</small></div><div class="metric"><span>PROPERTIES</span><strong>${c.properties?.length||1}</strong><small>Linked to one account</small></div></div>${panel('Property notes','SERVICE PROFILE',`<p class="note">${esc(c.notes||'No special notes saved.')}</p>`)}`;wireGo();return}if(v==='services'){setHeader('CUSTOMER PORTAL','Services');$('#content').innerHTML=`<div class="portal-services">${hero('SERVICES','Your services','Current plan and linked properties.')}<div class="grid two">${panel(c.plan,'ACTIVE PLAN',`<div class="summary-box"><strong>${money(c.monthlyValue)} / month</strong><span>Next service: ${esc(c.nextService||'To schedule')}</span><span>Billing: ${esc(c.billingMethod||'Per Service')} · ${esc(c.preferredContact||'Phone')}</span></div>`)}${panel('Properties','ACCOUNT LOCATIONS',`<div class="table">${(c.properties||[]).map(p=>`<div class="tr"><div><strong>${esc(p.label)}</strong><span>${esc(p.address)}</span></div><div><small>${esc(p.serviceNotes||'')}</small></div><div></div></div>`).join('')}</div>`)}</div></div>`;return}if(v==='billing'){setHeader('CUSTOMER PORTAL','Billing');$('#content').innerHTML=hero('BILLING','Invoices','Only invoices attached to this customer account are visible.')+panel('Invoice history','YOUR ACCOUNT',invoiceTable(data.invoices.filter(i=>i.customerId===c.id)));return}setHeader('CUSTOMER PORTAL','Messages');const reqs=data.customerRequests.filter(r=>r.customerId===c.id);$('#content').innerHTML=hero('MESSAGES','Request service or send a note','Customer requests enter the same operating system used by office staff.')+`<div class="grid two">${panel('New request','CUSTOMER TO OFFICE',`<form id="requestForm" class="form-grid">${select('Request type','type',['Add-on service','Schedule change','Billing question','Property note','Other'],'Add-on service')}${textarea('Message','message','')}<div class="form-span"><button class="btn primary">Send request</button></div></form>`)}${panel('Request history','ACCOUNT',requestTable(reqs))}</div>`;$('#requestForm').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,'/api/customer-requests','POST',{customerId:c.id});toast('Request sent');load('messages')}}
function closeMenu(){document.body.classList.remove('menu-open')}$('#roleSelect').onchange=e=>{role=e.target.value;customerId='';history.replaceState(null,'',`/app?role=${role}`);load()};$('#menuBtn').onclick=e=>{e.stopPropagation();document.body.classList.toggle('menu-open')};document.querySelector('.main').addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('#menuBtn'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();closeModal()}});load();
